import{_ as n,H as a,f as p,i as e}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"20｜有章可循：Rules 规则系统深度剖析","description":"","frontmatter":{},"headers":[{"level":2,"title":"两种规则，两个世界","slug":"两种规则-两个世界","link":"#两种规则-两个世界","children":[]},{"level":2,"title":"指令规则——.claude/rules/ 完全指南","slug":"指令规则——-claude-rules-完全指南","link":"#指令规则——-claude-rules-完全指南","children":[{"level":3,"title":"它到底是什么？","slug":"它到底是什么","link":"#它到底是什么","children":[]},{"level":3,"title":"两种加载模式","slug":"两种加载模式","link":"#两种加载模式","children":[]},{"level":3,"title":"什么时候该从 CLAUDE.md 拆到 rules？","slug":"什么时候该从-claude-md-拆到-rules","link":"#什么时候该从-claude-md-拆到-rules","children":[]},{"level":3,"title":"实战：一个全栈项目的 rules 拆分","slug":"实战-一个全栈项目的-rules-拆分","link":"#实战-一个全栈项目的-rules-拆分","children":[]}]},{"level":2,"title":"权限规则——行为管控的硬约束","slug":"权限规则——行为管控的硬约束","link":"#权限规则——行为管控的硬约束","children":[{"level":3,"title":"基本结构与评估逻辑","slug":"基本结构与评估逻辑","link":"#基本结构与评估逻辑","children":[]},{"level":3,"title":"权限规则覆盖的工具范围","slug":"权限规则覆盖的工具范围","link":"#权限规则覆盖的工具范围","children":[]},{"level":3,"title":"配置层级体系","slug":"配置层级体系","link":"#配置层级体系","children":[]},{"level":3,"title":"权限规则在扩展机制中的渗透","slug":"权限规则在扩展机制中的渗透","link":"#权限规则在扩展机制中的渗透","children":[]}]},{"level":2,"title":"两种规则的协同——一个完整案例","slug":"两种规则的协同——一个完整案例","link":"#两种规则的协同——一个完整案例","children":[{"level":3,"title":"指令规则部分","slug":"指令规则部分","link":"#指令规则部分","children":[]},{"level":3,"title":"权限规则部分","slug":"权限规则部分","link":"#权限规则部分","children":[]}]},{"level":2,"title":"架构定位与最佳实践","slug":"架构定位与最佳实践","link":"#架构定位与最佳实践","children":[{"level":3,"title":"Rules 在架构中的定位","slug":"rules-在架构中的定位","link":"#rules-在架构中的定位","children":[]},{"level":3,"title":"实用模板","slug":"实用模板","link":"#实用模板","children":[]},{"level":3,"title":"常见错误清单","slug":"常见错误清单","link":"#常见错误清单","children":[]}]},{"level":2,"title":"总结一下","slug":"总结一下","link":"#总结一下","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"下一讲预告","slug":"下一讲预告","link":"#下一讲预告","children":[]}],"relativePath":"ClaudeCode工程化实战/20｜有章可循：Rules规则系统深度剖析.md","filePath":"ClaudeCode工程化实战/20｜有章可循：Rules规则系统深度剖析.md","lastUpdated":1779815462000}'),l={name:"ClaudeCode工程化实战/20｜有章可循：Rules规则系统深度剖析.md"};function t(i,s,o,c,d,u){return a(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="_20-有章可循-rules-规则系统深度剖析" tabindex="-1">20｜有章可循：Rules 规则系统深度剖析 <a class="header-anchor" href="#_20-有章可循-rules-规则系统深度剖析" aria-label="Permalink to &quot;20｜有章可循：Rules 规则系统深度剖析&quot;">​</a></h1><blockquote><p>释题：有章可循。Claude Code 的“规则”不止一种——指令规则告诉 Claude 该怎么做，权限规则告诉 Claude 能做什么。前者是员工手册，后者是门禁系统，两套规则协同运作，才构成完整的行为约束体系。</p></blockquote><p>你好，我是黄佳。</p><p>上一讲我们学习了 Headless 模式，让 Claude Code 在无人值守的情况下嵌入 CI/CD 流水线自动运行。Headless 解决了没有人盯着的问题，但也让一个追问变得更加尖锐， <strong>没人盯着的时候，谁来定规矩？</strong></p><p>这就引出了今天的主题—— <strong>规则系统</strong>。</p><p>我发现一个有趣的现象：很多同学把两种“规则“搞混了。有人问“rules 目录里能不能禁止 Claude 执行 <code>rm</code> 命令？”答案是不能，那是权限规则的事；也有人问“settings.json 里能不能告诉 Claude 用 TypeScript 写代码？”答案也是不能，那是指令规则的事。</p><p><strong>这两种规则解决的是完全不同的问题。</strong> 今天我们就来把 Claude Code 中所有规则的全貌讲清楚。</p><h2 id="两种规则-两个世界" tabindex="-1">两种规则，两个世界 <a class="header-anchor" href="#两种规则-两个世界" aria-label="Permalink to &quot;两种规则，两个世界&quot;">​</a></h2><p>Claude Code 中的“规则”分布在两个完全不同的层面：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/964160/b5e2690885bdd4edf4172a16d24a494e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/964160/b5e2690885bdd4edf4172a16d24a494e.jpg" alt=""></a></p><p>我用一个比喻来帮你区分它们，指令规则像公司的员工手册，写着“代码提交前必须跑测试”，员工可以遵守，也可以偷懒。权限规则像门禁系统——没有卡就进不了机房，系统不给你选择。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/964160/300a0d19d9c046aab881a87a45ea561a.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/964160/300a0d19d9c046aab881a87a45ea561a.jpg" alt=""></a></p><p><strong>指令规则是 Claude 的认知约束，权限规则是客户端的行为约束。</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/964160/4c5c473a3d4c3a7ayy7b59ayye3d0786.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/964160/4c5c473a3d4c3a7ayy7b59ayye3d0786.jpg" alt=""></a></p><h2 id="指令规则——-claude-rules-完全指南" tabindex="-1">指令规则——.claude/rules/ 完全指南 <a class="header-anchor" href="#指令规则——-claude-rules-完全指南" aria-label="Permalink to &quot;指令规则——.claude/rules/ 完全指南&quot;">​</a></h2><p>也许看完前面说的你还是有点懵，别急，咱们继续探索规则背后的工作机制。</p><h3 id="它到底是什么" tabindex="-1">它到底是什么？ <a class="header-anchor" href="#它到底是什么" aria-label="Permalink to &quot;它到底是什么？&quot;">​</a></h3><p><code>.claude/rules/</code> 目录下的每个 <code>.md</code> 文件，本质上就是一段会被注入 System Prompt 的文本。它和 CLAUDE.md 没有本质区别——都是 Claude 在每轮 API 调用中“看到”的指令。唯一的结构化优势是，它可以按主题拆分成多个文件，还支持条件加载。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.claude/</span></span>
<span class="line"><span>└── rules/</span></span>
<span class="line"><span>    ├── typescript.md       # TypeScript 编码规范</span></span>
<span class="line"><span>    ├── testing.md          # 测试规范（有 paths 条件）</span></span>
<span class="line"><span>    ├── api-design.md       # API 设计规范（有 paths 条件）</span></span>
<span class="line"><span>    └── security.md         # 安全规范（全局生效）</span></span></code></pre></div><h3 id="两种加载模式" tabindex="-1">两种加载模式 <a class="header-anchor" href="#两种加载模式" aria-label="Permalink to &quot;两种加载模式&quot;">​</a></h3><p>这是 rules 最重要的设计细节，也是最多人搞错的地方。</p><p><strong>模式一：全局加载（无 paths 字段）</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># security.md —— 没有 YAML 头部，或有头部但不含 paths</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 安全规范</span></span>
<span class="line"><span>- 不在代码中硬编码密码或 API Key</span></span>
<span class="line"><span>- 所有用户输入必须做 sanitize</span></span>
<span class="line"><span>- SQL 查询使用参数化，不拼接字符串</span></span></code></pre></div><p>这种 rule 在会话启动时就加载进上下文，行为和写在 CLAUDE.md 里完全一样。拆出来的唯一好处是文件组织更清晰。</p><p><strong>模式二：条件加载（有 paths 字段）</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>paths:</span></span>
<span class="line"><span>  - &quot;src/**/*.test.ts&quot;</span></span>
<span class="line"><span>  - &quot;tests/**/*.ts&quot;</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 测试规范</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 命名</span></span>
<span class="line"><span>- 单元测试: \`*.test.ts\`</span></span>
<span class="line"><span>- 集成测试: \`*.integration.test.ts\`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 结构</span></span>
<span class="line"><span>使用 Arrange-Act-Assert 模式</span></span></code></pre></div><p>这种 rule 在会话启动时 <strong>不加载</strong>。只有当 Claude 读取或编辑匹配 <code>paths</code> 模式的文件时，才会被注入上下文。</p><p>这个设计很精妙——如果你的测试规范有 50 行，而你这次只是在改一个 CSS 样式，那这 50 行规范就不会浪费上下文空间。</p><p>但有一个关键细节， <strong>一旦加载，就不会卸载。</strong> paths 控制的是何时加载，不是何时生效。如果你在会话中先编辑了一个测试文件，testing.md 被加载了，然后你去改 CSS，testing.md 仍然在上下文里。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>会话开始</span></span>
<span class="line"><span>  → 加载全局 rules（无 paths 的）</span></span>
<span class="line"><span>  → testing.md 未加载 ✗</span></span>
<span class="line"><span></span></span>
<span class="line"><span>用户：帮我改一下 src/utils/format.ts</span></span>
<span class="line"><span>  → Claude 读取 format.ts</span></span>
<span class="line"><span>  → paths 不匹配，testing.md 仍未加载 ✗</span></span>
<span class="line"><span></span></span>
<span class="line"><span>用户：帮我给这个函数写个测试</span></span>
<span class="line"><span>  → Claude 创建 src/utils/format.test.ts</span></span>
<span class="line"><span>  → paths 匹配！testing.md 加载 ✓</span></span>
<span class="line"><span></span></span>
<span class="line"><span>用户：再帮我改一下 CSS</span></span>
<span class="line"><span>  → Claude 读取 styles.css</span></span>
<span class="line"><span>  → testing.md 仍在上下文中 ✓（不会卸载）</span></span></code></pre></div><h3 id="什么时候该从-claude-md-拆到-rules" tabindex="-1">什么时候该从 CLAUDE.md 拆到 rules？ <a class="header-anchor" href="#什么时候该从-claude-md-拆到-rules" aria-label="Permalink to &quot;什么时候该从 CLAUDE.md 拆到 rules？&quot;">​</a></h3><p>判断标准很简单，我们可以根据长度决策。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CLAUDE.md 的总长度如何？</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── &amp;lt; 200 行 → 不用拆，CLAUDE.md 一把梭</span></span>
<span class="line"><span>│               简单就是好，不要为了组织而组织</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── 200-500 行 → 考虑拆</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   └── 有没有&quot;只和特定文件类型相关&quot;的内容？</span></span>
<span class="line"><span>│       ├── 有 → 拆出来，加 paths</span></span>
<span class="line"><span>│       │       （如测试规范、前端规范、API 规范）</span></span>
<span class="line"><span>│       └── 没有 → 拆出来，不加 paths</span></span>
<span class="line"><span>│                 （纯粹为了文件组织清晰）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── &amp;gt; 500 行 → 必须拆</span></span>
<span class="line"><span>                CLAUDE.md 太长会稀释重要信息的权重</span></span>
<span class="line"><span>                把领域规范拆到 rules，CLAUDE.md 只留核心约定</span></span></code></pre></div><h3 id="实战-一个全栈项目的-rules-拆分" tabindex="-1">实战：一个全栈项目的 rules 拆分 <a class="header-anchor" href="#实战-一个全栈项目的-rules-拆分" aria-label="Permalink to &quot;实战：一个全栈项目的 rules 拆分&quot;">​</a></h3><p>假设你有一个 React + Express + PostgreSQL 的全栈项目，CLAUDE.md 膨胀到了 600 行（ <a href="https://github.com/huangjia2019/claude-code-engineering/blob/main/02-Memory/projects/03-bloated-claude-md/CLAUDE.md" target="_blank" rel="noreferrer">示例参考</a>）。我们如何拆分呢？</p><p><strong>拆分后的 CLAUDE.md（精简到 80 行以内）</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 项目概述</span></span>
<span class="line"><span>全栈 TypeScript 项目。前端 React 18 + Tailwind，后端 Express + Prisma + PostgreSQL。</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 命令</span></span>
<span class="line"><span>- \`pnpm dev\` — 启动前后端开发服务器</span></span>
<span class="line"><span>- \`pnpm test\` — 运行全部测试</span></span>
<span class="line"><span>- \`pnpm lint\` — ESLint + Prettier 检查</span></span>
<span class="line"><span>- \`pnpm db:migrate\` — 执行数据库迁移</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 核心约定</span></span>
<span class="line"><span>- 包管理器用 pnpm，不用 npm 或 yarn</span></span>
<span class="line"><span>- commit message 用 conventional commits 格式</span></span>
<span class="line"><span>- 所有 API 返回 { success: boolean, data?: T, error?: string }</span></span>
<span class="line"><span>- 环境变量通过 .env 管理，不硬编码</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 详细规范</span></span>
<span class="line"><span>领域规范见 .claude/rules/ 目录，按文件类型自动加载。</span></span></code></pre></div><p><strong>拆分出的 rules 文件</strong></p><p><code>.claude/rules/frontend.md</code>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>paths:</span></span>
<span class="line"><span>  - &quot;src/components/**&quot;</span></span>
<span class="line"><span>  - &quot;src/pages/**&quot;</span></span>
<span class="line"><span>  - &quot;src/hooks/**&quot;</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 前端规范</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 组件</span></span>
<span class="line"><span>- 函数式组件，不用 class 组件</span></span>
<span class="line"><span>- Props 用 interface 定义，命名 XxxProps</span></span>
<span class="line"><span>- 组件文件和样式文件同名同目录</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 状态管理</span></span>
<span class="line"><span>- 局部状态用 useState</span></span>
<span class="line"><span>- 跨组件状态用 Zustand</span></span>
<span class="line"><span>- 服务端状态用 TanStack Query</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 样式</span></span>
<span class="line"><span>- Tailwind 优先，复杂样式用 CSS Modules</span></span>
<span class="line"><span>- 响应式断点：sm(640) md(768) lg(1024) xl(1280)</span></span></code></pre></div><p><code>.claude/rules/backend.md</code>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>paths:</span></span>
<span class="line"><span>  - &quot;server/**&quot;</span></span>
<span class="line"><span>  - &quot;src/api/**&quot;</span></span>
<span class="line"><span>  - &quot;prisma/**&quot;</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 后端规范</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 路由</span></span>
<span class="line"><span>- RESTful 风格，资源名用复数</span></span>
<span class="line"><span>- 路由文件放 server/routes/，一个资源一个文件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 数据库</span></span>
<span class="line"><span>- 所有查询通过 Prisma ORM，不写原生 SQL</span></span>
<span class="line"><span>- 迁移文件不手动编辑</span></span>
<span class="line"><span>- 关联查询用 include，不用多次查询</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 错误处理</span></span>
<span class="line"><span>- 业务错误抛 AppError(code, message)</span></span>
<span class="line"><span>- 统一在 errorHandler 中间件中捕获</span></span></code></pre></div><p><code>.claude/rules/testing.md</code>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>paths:</span></span>
<span class="line"><span>  - &quot;**/*.test.ts&quot;</span></span>
<span class="line"><span>  - &quot;**/*.test.tsx&quot;</span></span>
<span class="line"><span>  - &quot;**/*.spec.ts&quot;</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 测试规范</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 工具</span></span>
<span class="line"><span>- 单元测试：Vitest</span></span>
<span class="line"><span>- 组件测试：Testing Library</span></span>
<span class="line"><span>- E2E：Playwright</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 结构</span></span>
<span class="line"><span>- Arrange-Act-Assert 模式</span></span>
<span class="line"><span>- 每个 describe 对应一个函数或组件</span></span>
<span class="line"><span>- Mock 外部依赖，不 mock 内部模块</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 覆盖率</span></span>
<span class="line"><span>- 业务逻辑 &amp;gt; 80%</span></span>
<span class="line"><span>- 工具函数 &amp;gt; 90%</span></span>
<span class="line"><span>- UI 组件关注交互，不关注快照</span></span></code></pre></div><p><code>.claude/rules/security.md</code>（注意，没有 paths，全局生效）：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 安全规范</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 用户输入在使用前必须 validate + sanitize</span></span>
<span class="line"><span>- SQL 参数化（Prisma 默认做到了）</span></span>
<span class="line"><span>- XSS 防护：不使用 dangerouslySetInnerHTML</span></span>
<span class="line"><span>- CORS 只允许白名单域名</span></span>
<span class="line"><span>- 敏感信息（API Key、数据库密码）只放 .env</span></span>
<span class="line"><span>- 认证 token 用 httpOnly cookie，不存 localStorage</span></span></code></pre></div><p>拆完之后，CLAUDE.md 从 600 行变成 80 行，但规范一条都没少——只是按需加载了。当 Claude 在改前端组件时，它看到的是 CLAUDE.md + frontend.md + security.md。当它在写测试时，看到的是 CLAUDE.md + testing.md + security.md。精准、高效。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/964160/d1a7bee9448f17bc595a2c023269e820.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/964160/d1a7bee9448f17bc595a2c023269e820.jpg" alt=""></a></p><h2 id="权限规则——行为管控的硬约束" tabindex="-1">权限规则——行为管控的硬约束 <a class="header-anchor" href="#权限规则——行为管控的硬约束" aria-label="Permalink to &quot;权限规则——行为管控的硬约束&quot;">​</a></h2><p>指令规则告诉 Claude“你应该怎么做”，权限规则告诉 Claude“你被允许做什么”。</p><p>权限规则写在 <code>.claude/settings.json</code> 或 <code>.claude/settings.local.json</code> 中，由 Claude Code 客户端在工具调用前 <strong>硬拦截</strong>。Claude 根本看不到这些规则——它只知道某个操作被允许了或被拒绝了。</p><h3 id="基本结构与评估逻辑" tabindex="-1">基本结构与评估逻辑 <a class="header-anchor" href="#基本结构与评估逻辑" aria-label="Permalink to &quot;基本结构与评估逻辑&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;permissions&quot;: {</span></span>
<span class="line"><span>    &quot;allow&quot;: [</span></span>
<span class="line"><span>      &quot;Bash(npm run *)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(git status)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(git diff *)&quot;,</span></span>
<span class="line"><span>      &quot;Read&quot;</span></span>
<span class="line"><span>    ],</span></span>
<span class="line"><span>    &quot;deny&quot;: [</span></span>
<span class="line"><span>      &quot;Bash(rm -rf *)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(curl *)&quot;,</span></span>
<span class="line"><span>      &quot;Edit(.env)&quot;</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>评估顺序：deny → ask → allow。</strong> 第一个匹配的规则胜出，deny 总是优先。就算你在 allow 里写了 <code>Bash(rm -rf *)</code>，如果 deny 里也有这条，deny 赢。安全规则应该有最高话语权。</p><h3 id="权限规则覆盖的工具范围" tabindex="-1">权限规则覆盖的工具范围 <a class="header-anchor" href="#权限规则覆盖的工具范围" aria-label="Permalink to &quot;权限规则覆盖的工具范围&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>内置工具的权限控制：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Bash(command pattern)      → 控制 Shell 命令的执行</span></span>
<span class="line"><span>  Read(file pattern)         → 控制文件的读取</span></span>
<span class="line"><span>  Edit(file pattern)         → 控制文件的编辑</span></span>
<span class="line"><span>  Write(file pattern)        → 控制文件的创建</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  WebFetch(domain:pattern)   → 控制网页抓取的域名范围</span></span>
<span class="line"><span>  WebSearch                  → 控制是否允许网络搜索</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  mcp__server__tool          → 控制 MCP 工具的使用</span></span>
<span class="line"><span>  Skill(skill-name)          → 控制 Skill 的调用</span></span>
<span class="line"><span>  Task(agent-name)           → 控制子代理的调用</span></span></code></pre></div><h3 id="配置层级体系" tabindex="-1">配置层级体系 <a class="header-anchor" href="#配置层级体系" aria-label="Permalink to &quot;配置层级体系&quot;">​</a></h3><p>权限配置可以在四个层级设置，高优先级覆盖低优先级。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/964160/d1264e131a814c20bbbc5e2a87e7809f.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/964160/d1264e131a814c20bbbc5e2a87e7809f.jpg" alt=""></a></p><p><strong>关键规则：高层级的 deny 不可被低层级覆盖。</strong> 如果组织策略禁止了 <code>Bash(curl *)</code>，项目配置和个人配置都无法解除这个限制。这是企业级安全管控的基石。</p><h3 id="权限规则在扩展机制中的渗透" tabindex="-1">权限规则在扩展机制中的渗透 <a class="header-anchor" href="#权限规则在扩展机制中的渗透" aria-label="Permalink to &quot;权限规则在扩展机制中的渗透&quot;">​</a></h3><p>权限规则不仅存在于 settings.json 中，它还渗透到了 Claude Code 的各个扩展机制里。</p><p><strong>Skills 中的 allowed-tools</strong>，Skill 被触发时只能使用白名单中的工具：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: code-reviewing</span></span>
<span class="line"><span>description: Review code for quality and security issues</span></span>
<span class="line"><span>allowed-tools:</span></span>
<span class="line"><span>  - Read</span></span>
<span class="line"><span>  - Grep</span></span>
<span class="line"><span>  - Glob</span></span>
<span class="line"><span>---</span></span></code></pre></div><p><strong>Sub-Agents 中的 tools</strong>，子代理的工具集更加严格，甚至拿不到主对话的 CLAUDE.md。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: code-reviewer</span></span>
<span class="line"><span>tools: Read, Grep, Glob</span></span>
<span class="line"><span>model: sonnet</span></span>
<span class="line"><span>---</span></span></code></pre></div><p><strong>Hooks 中的动态拦截</strong>，最灵活的权限控制，可以根据动态条件决定是否放行。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;hooks&quot;: {</span></span>
<span class="line"><span>    &quot;PreToolUse&quot;: [</span></span>
<span class="line"><span>      {</span></span>
<span class="line"><span>        &quot;matcher&quot;: &quot;Bash&quot;,</span></span>
<span class="line"><span>        &quot;hooks&quot;: [</span></span>
<span class="line"><span>          {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;command&quot;,</span></span>
<span class="line"><span>            &quot;command&quot;: &quot;./hooks/block-dangerous.sh&quot;</span></span>
<span class="line"><span>          }</span></span>
<span class="line"><span>        ]</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这三者共同构成了 <strong>权限纵深防御体系</strong>。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工具调用请求</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>第一关：settings.json 的 deny 规则</span></span>
<span class="line"><span>  → 命中？直接拦截，不可绕过</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>第二关：Hooks 的 PreToolUse 拦截</span></span>
<span class="line"><span>  → 脚本返回非零？拦截，可自定义逻辑</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>第三关：Skill/Agent 的 allowed-tools 限制</span></span>
<span class="line"><span>  → 不在白名单？拦截</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>第四关：settings.json 的 allow 规则 / 用户交互审批</span></span>
<span class="line"><span>  → 在白名单？自动放行</span></span>
<span class="line"><span>  → 不在任何规则中？弹窗询问用户</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>工具执行</span></span></code></pre></div><h2 id="两种规则的协同——一个完整案例" tabindex="-1">两种规则的协同——一个完整案例 <a class="header-anchor" href="#两种规则的协同——一个完整案例" aria-label="Permalink to &quot;两种规则的协同——一个完整案例&quot;">​</a></h2><p>让我们用一个真实场景把两种规则串起来：你的团队有一个支付服务项目，既需要编码规范（指令规则），也需要安全管控（权限规则）。</p><h3 id="指令规则部分" tabindex="-1">指令规则部分 <a class="header-anchor" href="#指令规则部分" aria-label="Permalink to &quot;指令规则部分&quot;">​</a></h3><p><code>CLAUDE.md</code>（精简版，~60 行）：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 支付服务</span></span>
<span class="line"><span>Node.js + TypeScript + Stripe API，处理用户支付流程。</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 命令</span></span>
<span class="line"><span>- \`pnpm dev\` — 启动开发服务器</span></span>
<span class="line"><span>- \`pnpm test\` — 运行测试</span></span>
<span class="line"><span>- \`pnpm lint\` — 代码检查</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 核心约定</span></span>
<span class="line"><span>- 所有金额用 cents（整数），不用浮点数</span></span>
<span class="line"><span>- 日志必须包含 requestId，便于追踪</span></span>
<span class="line"><span>- 不在日志中打印卡号、CVV 等敏感信息</span></span></code></pre></div><p><code>.claude/rules/stripe.md</code>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>paths:</span></span>
<span class="line"><span>  - &quot;src/payments/**&quot;</span></span>
<span class="line"><span>  - &quot;src/webhooks/**&quot;</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Stripe 集成规范</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Webhook 处理</span></span>
<span class="line"><span>- 始终验证 webhook 签名（stripe.webhooks.constructEvent）</span></span>
<span class="line"><span>- 幂等处理：用 event.id 去重</span></span>
<span class="line"><span>- 先返回 200，再异步处理业务逻辑</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 错误处理</span></span>
<span class="line"><span>- StripeCardError → 返回用户友好消息</span></span>
<span class="line"><span>- StripeRateLimitError → 指数退避重试</span></span>
<span class="line"><span>- 其他 Stripe 错误 → 记录日志 + 告警</span></span></code></pre></div><h3 id="权限规则部分" tabindex="-1">权限规则部分 <a class="header-anchor" href="#权限规则部分" aria-label="Permalink to &quot;权限规则部分&quot;">​</a></h3><p><code>.claude/settings.json</code>（团队共享）：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;permissions&quot;: {</span></span>
<span class="line"><span>    &quot;allow&quot;: [</span></span>
<span class="line"><span>      &quot;Bash(pnpm *)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(git status)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(git diff *)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(git log *)&quot;,</span></span>
<span class="line"><span>      &quot;Read&quot;,</span></span>
<span class="line"><span>      &quot;Glob&quot;,</span></span>
<span class="line"><span>      &quot;Grep&quot;</span></span>
<span class="line"><span>    ],</span></span>
<span class="line"><span>    &quot;deny&quot;: [</span></span>
<span class="line"><span>      &quot;Bash(curl *)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(wget *)&quot;,</span></span>
<span class="line"><span>      &quot;Read(./.env)&quot;,</span></span>
<span class="line"><span>      &quot;Read(./.env.*)&quot;,</span></span>
<span class="line"><span>      &quot;Edit(./.env)&quot;,</span></span>
<span class="line"><span>      &quot;Edit(./.env.*)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(rm -rf *)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(* --force)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(stripe *)&quot;</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>注意这个 deny 列表的设计意图：</p><ul><li><p>禁止 <code>curl/wget</code>——防止 Claude 自行调用外部 API（包括 Stripe API）</p></li><li><p>禁止读写 <code>.env</code>——保护 Stripe Secret Key 等敏感配置</p></li><li><p>禁止 <code>stripe *</code>——防止 Claude 用 Stripe CLI 直接操作生产环境</p></li><li><p>禁止 <code>rm -rf</code> 和 <code>--force</code>——防止破坏性操作</p></li></ul><p><strong>两种规则各司其职，</strong> 指令规则告诉 Claude“处理 webhook 要验签、金额用 cents”——这是认知层面的约束，让 Claude 写出正确的代码。权限规则告诉客户端“不许读 .env、不许执行 stripe CLI”——这是行为层面的约束，从系统层面堵住安全漏洞。</p><p>即使 Claude“忘记”了指令规则中不在日志中打印卡号的要求，权限规则也能确保它无法读取 .env 中的 Stripe Key。 <strong>纵深防御，不依赖单一层面。</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/964160/d0c5eb669fdf10fea5645a495608a080.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/964160/d0c5eb669fdf10fea5645a495608a080.jpg" alt=""></a></p><h2 id="架构定位与最佳实践" tabindex="-1">架构定位与最佳实践 <a class="header-anchor" href="#架构定位与最佳实践" aria-label="Permalink to &quot;架构定位与最佳实践&quot;">​</a></h2><h3 id="rules-在架构中的定位" tabindex="-1">Rules 在架构中的定位 <a class="header-anchor" href="#rules-在架构中的定位" aria-label="Permalink to &quot;Rules 在架构中的定位&quot;">​</a></h3><p>“规则”不是架构中的一个方块，而是 <strong>渗透在每一层中的横切关注点。</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/964160/faab1a88f84f5ef78e9ed57a897cf906.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/964160/faab1a88f84f5ef78e9ed57a897cf906.jpg" alt=""></a></p><ul><li><p><strong>指令层</strong> 有指令规则（CLAUDE.md、.claude/rules/）</p></li><li><p><strong>能力层</strong> 有能力规则（Skills 的 allowed-tools、Agent 的 tools）</p></li><li><p><strong>管控层</strong> 有权限规则（settings.json、Hooks、CLI 参数）</p></li></ul><p>这就像安全不是软件中的一个模块，而是贯穿所有模块的设计原则。这里我也顺便说明一下 Rules 的正确学习路径。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/964160/481839c6e52e1ede9fb59b5d935de71b.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/964160/481839c6e52e1ede9fb59b5d935de71b.jpg" alt=""></a></p><p>每一讲都在从自己的角度教 Rules 的一个切面。这一讲的价值，就是帮你把这些碎片拼成全景图。</p><h3 id="实用模板" tabindex="-1">实用模板 <a class="header-anchor" href="#实用模板" aria-label="Permalink to &quot;实用模板&quot;">​</a></h3><p><strong>rules 目录的标准结构</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.claude/</span></span>
<span class="line"><span>├── settings.json          ← 权限规则（团队共享）</span></span>
<span class="line"><span>├── settings.local.json    ← 个人权限覆盖（.gitignore）</span></span>
<span class="line"><span>└── rules/</span></span>
<span class="line"><span>    ├── coding.md          ← 全局编码规范（无 paths）</span></span>
<span class="line"><span>    ├── frontend.md        ← 前端规范（paths: src/components/**)</span></span>
<span class="line"><span>    ├── backend.md         ← 后端规范（paths: server/**)</span></span>
<span class="line"><span>    ├── testing.md         ← 测试规范（paths: **/*.test.*)</span></span>
<span class="line"><span>    └── security.md        ← 安全规范（无 paths，全局生效）</span></span></code></pre></div><p><strong>权限规则的安全基线</strong>（适用于大多数团队）：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;permissions&quot;: {</span></span>
<span class="line"><span>    &quot;allow&quot;: [</span></span>
<span class="line"><span>      &quot;Read&quot;,</span></span>
<span class="line"><span>      &quot;Glob&quot;,</span></span>
<span class="line"><span>      &quot;Grep&quot;,</span></span>
<span class="line"><span>      &quot;Bash(npm run *)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(pnpm *)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(git status)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(git diff *)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(git log *)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(node *)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(npx *)&quot;</span></span>
<span class="line"><span>    ],</span></span>
<span class="line"><span>    &quot;deny&quot;: [</span></span>
<span class="line"><span>      &quot;Bash(rm -rf *)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(* --force)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(curl *)&quot;,</span></span>
<span class="line"><span>      &quot;Bash(wget *)&quot;,</span></span>
<span class="line"><span>      &quot;Read(./.env)&quot;,</span></span>
<span class="line"><span>      &quot;Read(./.env.*)&quot;,</span></span>
<span class="line"><span>      &quot;Edit(./.env)&quot;,</span></span>
<span class="line"><span>      &quot;Edit(./.env.*)&quot;,</span></span>
<span class="line"><span>      &quot;Read(~/.ssh/*)&quot;,</span></span>
<span class="line"><span>      &quot;Read(~/.aws/*)&quot;</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这个模版你要根据你的项目调整。如果用 Python 就把 <code>pnpm</code> 换成 <code>pip/uv</code>；如果需要 Claude 访问特定 API，就在 allow 中加 <code>WebFetch(domain:your-api.com)</code>。</p><h3 id="常见错误清单" tabindex="-1">常见错误清单 <a class="header-anchor" href="#常见错误清单" aria-label="Permalink to &quot;常见错误清单&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>错误 1: 在 rules/*.md 中写权限控制</span></span>
<span class="line"><span>  ❌ .claude/rules/security.md 里写：&quot;禁止执行 rm -rf 命令&quot;</span></span>
<span class="line"><span>  → Claude 可能遵守，也可能忘记。这是软约束。</span></span>
<span class="line"><span>  ✅ 在 settings.json 的 deny 中写：Bash(rm -rf *)</span></span>
<span class="line"><span>  → 客户端硬拦截，Claude 连尝试的机会都没有。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>错误 2: 在 settings.json 中写编码规范</span></span>
<span class="line"><span>  ❌ settings.json 无法表达&quot;用 TypeScript 写代码&quot;这样的指令</span></span>
<span class="line"><span>  → 它只能控制 allow/deny，不能传递知识</span></span>
<span class="line"><span>  ✅ 在 CLAUDE.md 或 rules/*.md 中写编码规范</span></span>
<span class="line"><span></span></span>
<span class="line"><span>错误 3: rules 文件之间互相矛盾</span></span>
<span class="line"><span>  ❌ coding.md 说&quot;缩进用 2 空格&quot;，frontend.md 说&quot;缩进用 4 空格&quot;</span></span>
<span class="line"><span>  → Claude 会困惑，行为不可预测</span></span>
<span class="line"><span>  ✅ 全局规范放 coding.md，领域规范只写领域特有的</span></span>
<span class="line"><span></span></span>
<span class="line"><span>错误 4: paths 写得太宽或太窄</span></span>
<span class="line"><span>  ❌ paths: [&quot;**/*&quot;] → 等于没写 paths，不如去掉</span></span>
<span class="line"><span>  ❌ paths: [&quot;src/components/UserProfile.tsx&quot;] → 太窄，基本不会触发</span></span>
<span class="line"><span>  ✅ paths: [&quot;src/components/**&quot;] → 合理粒度</span></span>
<span class="line"><span></span></span>
<span class="line"><span>错误 5: 以为子代理能继承 rules</span></span>
<span class="line"><span>  ❌ 期望子代理自动遵守 .claude/rules/ 中的规范</span></span>
<span class="line"><span>  → 子代理看不到主对话的任何记忆文件</span></span>
<span class="line"><span>  ✅ 把关键规范写进子代理的 Markdown body 或通过 Skills 注入</span></span></code></pre></div><h2 id="总结一下" tabindex="-1">总结一下 <a class="header-anchor" href="#总结一下" aria-label="Permalink to &quot;总结一下&quot;">​</a></h2><p>这一讲我们把 Claude Code 中所有的“规则“做了一次全景梳理。</p><p><strong>两种规则，两个世界</strong>，明白两个规则的本质是用对它们的前提。指令规则（CLAUDE.md、.claude/rules/）是认知约束，注入 System Prompt 让 Claude 知道该怎么做；权限规则（settings.json permissions）是行为约束，由客户端硬拦截让 Claude 做不了不该做的事。</p><p><strong>指令规则有两种加载模式</strong>，无 paths 字段的全局加载，有 paths 字段的条件加载。条件加载省 token 又精准，但加载后不会卸载。CLAUDE.md 超过 200 行就考虑拆分，超过 500 行必须拆分。3-5 个 rules 文件是最佳规模。</p><p><strong>权限规则重点掌握它的纵深防御设计，</strong> settings.json deny → Hooks PreToolUse → Skill/Agent allowed-tools → settings.json allow / 用户审批，四层拦截逐级递进。高层级 deny 不可被低层级覆盖。</p><p><strong>Rules 不是独立组件，是横切关注点</strong>，它渗透在 Memory、Tools、Skills、SubAgents、Hooks 每一讲中。指令规则让 Claude 做对，权限规则让 Claude 做不了错。两者协同，才是完整的规则体系。</p><p>到这里，我们已经完整学习了 Claude Code 的所有核心扩展机制——Memory（记忆）、SubAgents（分工）、Skills（领域能力）、Commands（标准流程）、Hooks（安全防护）、MCP（外部连接）、Tools（工具基础）、Rules（行为约束）。所有这些都有一个共同前提：需要人在终端前交互。下一讲，我们将打破这个前提。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>你的项目目前有 <code>.claude/rules/</code> 目录吗？如果没有，试着评估一下你的 CLAUDE.md 长度——是否已经到了需要拆分的程度？如果要拆，你会拆出哪几个 rule 文件？</p></li><li><p>假设你的团队中有实习生使用 Claude Code，你会在 <code>settings.json</code> 的 deny 列表中增加哪些规则？与正式员工的配置有什么不同？</p></li><li><p>指令规则是“软约束”——Claude 可能不遵守。如果你有一条 <strong>绝对不能违反</strong> 的规则（比如“永远不要删除生产数据库的表”），你会只写在 <code>.claude/rules/</code> 中吗？还是会在权限规则和 Hooks 中也加上对应的硬约束？请设计一个完整的防护方案。</p></li><li><p>这节课我们强调“rules 不是独立组件，是横切关注点”。在传统软件工程中，也有一个著名的横切关注点——日志（Logging）。它和 Rules 有什么相似之处？这种相似性能给你什么设计启发？</p></li></ol><h2 id="下一讲预告" tabindex="-1">下一讲预告 <a class="header-anchor" href="#下一讲预告" aria-label="Permalink to &quot;下一讲预告&quot;">​</a></h2><p>到目前为止，我们学习的所有功能都是通过 <strong>配置文件和命令行</strong> 驱动 Claude Code。但有时候，你需要更精细的控制——用代码来驱动 AI。</p><p>第 21 讲，我们将学习 <strong>Agent SDK 基础</strong>——用 Python/TypeScript 编程驱动 Claude 执行任务。你将学会如何在代码中创建 Claude 会话、发送消息、处理响应，以及如何通过编程接口调用 Claude Code 的全部能力。Agent SDK 是从“使用 AI 工具”到“构建 AI 应用”的关键跨越。</p><p>欢迎你在留言区参与讨论，如果这节课对你有启发，别忘了分享给身边更多朋友。</p>`,114)])])}const g=n(l,[["render",t]]);export{h as __pageData,g as default};
